using System;using System.Collections.Generic;
public class BaseUnlockableAsset {public string id="",achievement_id="";public bool unlocked_with_achievement=true,needs_to_be_explored=true;public bool isTemplateAsset(){return id.StartsWith("$");}}
public class ItemAsset:BaseUnlockableAsset {public bool mod_can_be_given;}public class EquipmentAsset:ItemAsset {}public class ActorTrait:BaseUnlockableAsset {public bool can_be_given,can_be_removed;}public class OtherAsset:BaseUnlockableAsset{}
public class Library<T> {public List<T> list=new List<T>();}public class ItemLibrary:Library<EquipmentAsset> {public List<EquipmentAsset> pot_weapon_assets_all=new List<EquipmentAsset>(),pot_weapon_assets_unlocked=new List<EquipmentAsset>();public Dictionary<string,List<EquipmentAsset>> pot_equipment_by_groups_all=new Dictionary<string,List<EquipmentAsset>>(),pot_equipment_by_groups_unlocked=new Dictionary<string,List<EquipmentAsset>>();}
public class GameProgressData {public HashSet<string> unlocked_traits_actor=new HashSet<string>(),unlocked_equipment=new HashSet<string>(),achievements=new HashSet<string>();}public class GameProgress {public static GameProgress instance;internal GameProgressData data=new GameProgressData();}public static class AssetManager {public static Library<ActorTrait> traits;public static ItemLibrary items;public static Library<ItemAsset> items_modifiers;}
class UnlockTests {
 static int count;static void Check(bool b,string label){if(!b)throw new Exception(label);count++;}
 static void Main(){NativeUnlocks.Apply();Check(true,"cold initialization without managers");var weapon=new EquipmentAsset{id="shotgun",achievement_id="locked"};var armor=new EquipmentAsset{id="armor_adamantine"};var trait=new ActorTrait{id="immortal"};var mod=new ItemAsset{id="modifier"};AssetManager.items=new ItemLibrary();AssetManager.items.list.AddRange(new[]{weapon,armor});AssetManager.items.pot_weapon_assets_all.Add(weapon);AssetManager.items.pot_equipment_by_groups_all["armor"]=new List<EquipmentAsset>{armor};AssetManager.traits=new Library<ActorTrait>();AssetManager.traits.list.Add(trait);AssetManager.items_modifiers=new Library<ItemAsset>();AssetManager.items_modifiers.list.Add(mod);GameProgress.instance=new GameProgress();NativeUnlocks.EquipmentPools(AssetManager.items);
 Check(NativeUnlocks.Target(weapon)&&NativeUnlocks.Target(trait)&&NativeUnlocks.Target(mod)&&!NativeUnlocks.Target(new OtherAsset()),"availability limited to equipment and personal traits");Check(!weapon.unlocked_with_achievement&&!weapon.needs_to_be_explored&&weapon.achievement_id=="","equipment achievement and exploration locks removed");Check(trait.can_be_given&&trait.can_be_removed&&!trait.needs_to_be_explored,"all personal traits editable");Check(mod.mod_can_be_given&&!mod.unlocked_with_achievement,"item modifiers editable");Check(GameProgress.instance.data.unlocked_traits_actor.Contains("immortal")&&GameProgress.instance.data.unlocked_equipment.Count==2,"native unlock collections populated");Check(GameProgress.instance.data.achievements.Count==0,"achievements not fabricated");Check(AssetManager.items.pot_weapon_assets_unlocked.Contains(weapon)&&AssetManager.items.pot_equipment_by_groups_unlocked["armor"].Contains(armor),"native unlocked item pools complete");NativeUnlocks.EquipmentPools(AssetManager.items);Check(AssetManager.items.pot_weapon_assets_unlocked.Count==1&&GameProgress.instance.data.unlocked_equipment.Count==2,"unlocking is idempotent");Console.WriteLine(count+" unlock checks passed");}
}
